mapper.select:
SELECT COUNT(*)
FROM content_reports
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND reporter_id = #{reporterId}
  AND status = 'pending'

mapper.sql:
WHERE 1 = 1
AND r.status = #{status}
AND r.target_type = #{targetType}
AND ( r.reason LIKE CONCAT('%', #{keyword}, '%') OR r.detail LIKE CONCAT('%', #{keyword}, '%') OR l.title LIKE CONCAT('%', #{keyword}, '%') OR l.content LIKE CONCAT('%', #{keyword}, '%') OR lc.content LIKE CONCAT('%', #{keyword}, '%') OR ru.username LIKE CONCAT('%', #{keyword}, '%') OR rp.nickname LIKE CONCAT('%', #{keyword}, '%') )
